Game.data = {"realms":[{"name":"Mortal","need":100,"life":0},{"name":"Qi Condensation","need":300,"life":5},{"name":"Foundation Establishment","need":850,"life":8},{"name":"Golden Core","need":2200,"life":12},{"name":"Nascent Soul","need":6000,"life":22},{"name":"Soul Transformation","need":18000,"life":40},{"name":"Immortal Ascension","need":null,"life":0}],"roots":[{"name":"Fire","mult":1,"brk":0},{"name":"Water","mult":1,"brk":0},{"name":"Wood","mult":1,"brk":0},{"name":"Metal","mult":1,"brk":0},{"name":"Earth","mult":1,"brk":0},{"name":"Heavenly","mult":1.8,"brk":0.15}],"flavor":{"names":["Li Wei","Chen Yu","Lin Xue","Zhao Ming","Wang Hao","Liu Yan","Xiao Feng","Mu Qing","Han Lei","Bai Lian","Ye Chen","Su Rou"],"quiet":["A quiet year passes in steady practice.","You spend the year tending your village chores and breathing exercises.","Seasons turn. Nothing remarkable happens.","You wander the hills, sensing the flow of qi.","The year slips by like river water.","You pass the year in calm routine."]},"balance":{"eventChance":0.75,"regen":{"min":0,"max":3,"perRealm":1},"oldAge":{"start":0.8,"drainMin":1,"drainMax":5},"seclusion":{"qiBonus":1.5,"eventChance":0.25,"stopBelowHealth":30},"meditation":{"riskChance":0.1,"riskDamageMin":8,"riskDamageMax":22},"breakthrough":{"base":0.35,"failDamageMin":10,"failDamageMax":25,"successHeal":0}},"items":[{"id":"healing_pill","name":"Healing Pill","type":"consumable","desc":"Restores 25 health.","use":{"health":25},"price":25},{"id":"qi_pill","name":"Qi Gathering Pill","type":"consumable","desc":"Gain qi. Stronger at higher realms.","use":{"qi":{"base":30,"perRealm":30}},"price":35},{"id":"clarity_pill","name":"Clarity Pill","type":"consumable","desc":"Permanently gain 4 intelligence.","use":{"intelligence":4}},{"id":"longevity_pill","name":"Longevity Pill","type":"consumable","desc":"Extends your lifespan by 10 years.","use":{"lifespan":10}},{"id":"breakthrough_pill","name":"Breakthrough Pill","type":"consumable","desc":"Used automatically when you attempt a breakthrough: +15% success chance.","onBreakthrough":0.15,"price":70},{"id":"antidote","name":"Antidote","type":"consumable","desc":"Neutralizes poison. Some events let you use it.","price":15},{"id":"iron_sword","name":"Iron Sword","type":"equipment","slot":"weapon","desc":"+6 power in fights.","mods":{"power":6},"price":80},{"id":"spirit_blade","name":"Spirit Blade","type":"equipment","slot":"weapon","desc":"+14 power in fights.","mods":{"power":14}},{"id":"leather_vest","name":"Leather Vest","type":"equipment","slot":"armor","desc":"Reduces damage you take by 10%.","mods":{"guard":0.1},"price":60},{"id":"jade_robe","name":"Jade Silk Robe","type":"equipment","slot":"armor","desc":"Reduces damage by 20% and restores 1 extra health a year.","mods":{"guard":0.2,"regen":1}},{"id":"lucky_charm","name":"Lucky Charm","type":"equipment","slot":"talisman","desc":"+8 luck.","mods":{"luck":8},"price":70},{"id":"qi_pendant","name":"Qi Pendant","type":"equipment","slot":"talisman","desc":"+15% qi from cultivation.","mods":{"qiMult":0.15}},{"id":"sage_jade","name":"Sage's Jade","type":"equipment","slot":"talisman","desc":"+8 intelligence and +5% breakthrough chance.","mods":{"intelligence":8,"breakBonus":0.05}}],"events":[{"id":"winter","text":"A bitter winter grips your village. Food and firewood run low.","minAge":3,"maxAge":12,"weight":4,"choices":[{"label":"Brave the snow to gather firewood","outcomes":[{"chance":0.7,"text":"You return frozen but proud. Your body grows tougher.","effects":{"health":3,"karma":2}},{"text":"You catch a terrible chill.","effects":{"health":-15}}]},{"label":"Huddle by the fire","outcomes":[{"text":"You stay warm and listen to the elders' tales of immortals.","effects":{"intelligence":2}}]}]},{"id":"fever","text":"A raging fever lays you low.","minAge":1,"maxAge":14,"weight":4,"choices":[{"label":"Pay the village healer (10 gold)","if":["gold>=10"],"outcomes":[{"chance":0.85,"text":"The herbs work. You recover quickly.","effects":{"gold":-10,"health":2}},{"text":"The medicine barely helps.","effects":{"gold":-10,"health":-15}}]},{"label":"Tough it out","outcomes":[{"chance":0.5,"text":"You survive on sheer will. A strange warmth lingers in your belly.","effects":{"qi":8,"health":-5}},{"text":"The fever ravages you.","effects":{"health":-25}}]}]},{"id":"school","text":"The village teacher offers to tutor you after class.","minAge":5,"maxAge":12,"weight":3,"once":true,"choices":[{"label":"Study diligently","outcomes":[{"text":"You devour the scrolls.","effects":{"intelligence":6}}]},{"label":"Go play in the fields","outcomes":[{"text":"You have a wonderful day outdoors.","effects":{"health":3,"luck":3}}]}]},{"id":"bully","text":"Older kids corner you and demand your lunch.","minAge":6,"maxAge":14,"weight":3,"choices":[{"label":"Fight back","outcomes":[{"chance":0.45,"text":"You win, bruised but respected.","effects":{"health":-5,"luck":3}},{"text":"You get beaten badly.","effects":{"health":-15}}]},{"label":"Hand it over","outcomes":[{"text":"You go hungry but stay safe.","effects":{"health":-2,"karma":2}}]}]},{"id":"wanderer","text":"A wandering cultivator passes through your village and stops to stare at you. 'This child has a rare spark,' he murmurs.","minAge":6,"maxAge":14,"weight":8,"once":true,"choices":[{"label":"Beg him to teach you","outcomes":[{"text":"He shows you a basic breathing technique before leaving.","effects":{"qi":25,"intelligence":4,"setFlags":["taughtBasics"]}}]},{"label":"Hide behind your mother","outcomes":[{"text":"The stranger shrugs and walks on. The moment passes.","effects":{"luck":-2}}]}]},{"id":"retreat","text":"You consider a short seclusion to refine your cultivation.","minAge":8,"weight":5,"choices":[{"label":"Seclude yourself for a month","outcomes":[{"chance":0.12,"text":"Qi deviation strikes during the retreat!","effects":{"health":-20,"qi":15}},{"text":"The retreat bears fruit.","effects":{"qi":{"base":20,"perRealm":20}}}]},{"label":"Keep to your routine","outcomes":[{"text":"Steady habits keep you grounded.","effects":{"health":2}}]}]},{"id":"alchemy","text":"You have the materials to try your hand at alchemy.","minAge":14,"minRealm":1,"weight":3,"if":["gold>=30"],"choices":[{"label":"Refine a pill (30 gold)","if":["gold>=30"],"outcomes":[{"chance":0.4,"scale":{"intelligence":0.005},"bonus":[{"if":["root:Fire"],"add":0.15}],"text":"A fragrant pill forms: a Breakthrough Pill!","effects":{"gold":-30,"items":{"breakthrough_pill":1}}},{"text":"The furnace explodes in a cloud of smoke.","effects":{"gold":-30,"health":-8}}]},{"label":"Not now","outcomes":[{"text":"You save your materials."}]}]},{"id":"mission","text":"Your sect posts missions on the bounty board.","minAge":14,"weight":6,"if":["sect"],"choices":[{"label":"Take a dangerous mission","outcomes":[{"chance":0.6,"text":"You complete it brilliantly.","effects":{"gold":80,"qi":30,"items":{"healing_pill":1}}},{"text":"The mission goes horribly wrong.","effects":{"health":-30}}]},{"label":"Take a safe mission","outcomes":[{"text":"A modest but steady reward.","effects":{"gold":20,"qi":8}}]}]},{"id":"tribulation","text":"Dark clouds gather. A heavenly tribulation lightning descends upon you!","minAge":20,"minRealm":2,"weight":2,"choices":[{"label":"Endure it head on","outcomes":[{"chance":0.35,"scale":{"health":0.005},"text":"You forge your body in lightning!","effects":{"qi":{"base":100,"perRealm":30},"health":-15}},{"text":"The lightning devastates you.","effects":{"health":-45,"qi":-40}}]},{"label":"Shelter underground","outcomes":[{"text":"You lose the chance but survive.","effects":{"luck":-2,"qi":-10}}]}]},{"id":"frail","text":"Your body feels frail as the years weigh on you.","minAge":40,"weight":4,"if":["ageRatio>0.7"],"choices":[{"label":"Buy a rejuvenating tonic (40 gold)","if":["gold>=40"],"outcomes":[{"text":"The tonic restores some vigor.","effects":{"gold":-40,"health":20,"lifespan":3}}]},{"label":"Cultivate harder","outcomes":[{"text":"You push your limits.","effects":{"qi":30,"health":-10}}]}]},{"id":"beast","text":"A ferocious spirit beast blocks your path.","minAge":10,"weight":5,"choices":[{"label":"Fight it","outcomes":[{"chance":0.35,"scale":{"realm":0.12,"health":0.0025,"power":0.01},"text":"You slay the beast and harvest its core.","effects":{"gold":{"base":20,"perRealm":15},"qi":{"base":10,"perRealm":10}}},{"text":"The beast wounds you badly.","effects":{"health":-30}}]},{"label":"Flee","outcomes":[{"chance":0.7,"text":"You escape with your life."},{"text":"It catches you before you break free.","effects":{"health":-15}}]}]},{"id":"ambush","text":"Your rival's lackeys ambush you on a lonely road!","minAge":14,"minRealm":1,"weight":7,"if":["flag:hasRival","!flag:rivalDone"],"choices":[{"label":"Fight them","outcomes":[{"chance":0.5,"scale":{"realm":0.05,"power":0.01},"text":"You scatter them. The rival's enmity deepens.","effects":{"qi":15,"health":-8}},{"text":"You are outnumbered and beaten.","effects":{"health":-28}}]},{"label":"Trust your luck and slip away","outcomes":[{"chance":0,"scale":{"luck":0.01},"text":"Fortune smiles; you vanish into the mist."},{"text":"Bad luck! They catch you.","effects":{"health":-20}}]}]},{"id":"deviation","text":"Mid-cultivation, your qi suddenly runs wild through your meridians!","minAge":12,"minRealm":1,"weight":3,"if":["qi>30"],"choices":[{"label":"Suppress it with your mind","outcomes":[{"chance":0.3,"scale":{"intelligence":0.0067},"text":"You wrestle the qi under control and emerge stronger.","effects":{"qi":20,"intelligence":2}},{"text":"You fail; the backlash tears at you.","effects":{"health":-25,"qi":-30}}]},{"label":"Vent the energy","outcomes":[{"text":"You release the surge, losing some progress.","effects":{"qi":-20,"health":-5}}]}]},{"id":"poison","text":"You fall violently ill after a banquet. Someone has poisoned your cup!","minAge":12,"weight":2,"choices":[{"label":"Buy an antidote (20 gold)","if":["gold>=20"],"outcomes":[{"text":"The antidote saves you.","effects":{"gold":-20,"health":-5}}]},{"label":"Drink the antidote you carry","if":["item:antidote"],"outcomes":[{"text":"You swallow your antidote just in time.","effects":{"items":{"antidote":-1},"health":-3}}]},{"label":"Burn 20 qi to purge the toxin","if":["qi>=20"],"outcomes":[{"text":"You force the poison out through your pores.","effects":{"qi":-20,"health":-10}}]},{"label":"Endure it","outcomes":[{"chance":0.8,"scale":{"realm":0.04},"text":"You survive somehow.","effects":{"health":-30}},{"text":"The poison is too strong.","effects":{"die":"Died of poisoning"}}]}]},{"id":"bandits","text":"Bandits demand your purse on a mountain road.","minAge":12,"maxRealm":2,"weight":4,"choices":[{"label":"Pay them","outcomes":[{"text":"You hand over some coins.","effects":{"gold":-20}}]},{"label":"Fight","outcomes":[{"chance":0.4,"scale":{"realm":0.2,"power":0.01},"text":"You drive them off.","effects":{"gold":15,"karma":2}},{"text":"They beat you and take everything.","effects":{"health":-20,"gold":"-all"}}]}]},{"id":"peddler","text":"A traveling peddler spreads his wares on a blanket: charms, pills and curios.","minAge":10,"weight":4,"choices":[{"label":"Buy a lucky charm (40 gold)","if":["gold>=40"],"outcomes":[{"text":"The peddler swears it brought him luck, and now it is yours.","effects":{"gold":-40,"items":{"lucky_charm":1}}}]},{"label":"Buy three healing pills (30 gold)","if":["gold>=30"],"outcomes":[{"text":"A fair deal. You tuck the pills away.","effects":{"gold":-30,"items":{"healing_pill":3}}}]},{"label":"Haggle for a free sample","outcomes":[{"chance":0.35,"scale":{"luck":0.004},"text":"Amused, he tosses you a healing pill.","effects":{"items":{"healing_pill":1}}},{"text":"He waves you off with a laugh."}]}]},{"id":"old_tomb","text":"You stumble upon an unsealed tomb. A weathered coffin rests inside, with a faint blade glow beneath its lid.","minAge":16,"minRealm":1,"weight":2,"once":true,"choices":[{"label":"Open the coffin","outcomes":[{"chance":0.35,"scale":{"luck":0.004},"text":"The guardian spirit is long gone, and its blade is yours.","effects":{"karma":-3,"items":{"spirit_blade":1}}},{"text":"A curse lashes out as the lid lifts.","effects":{"health":-25}}]},{"label":"Pay respects and leave","outcomes":[{"text":"You bow to the dead and move on.","effects":{"karma":3}}]}]},{"id":"sect_armory","text":"Your sect opens its armory to disciples who have proven themselves. You may take one reward.","minAge":16,"weight":4,"once":true,"if":["sect"],"choices":[{"label":"Take an Iron Sword","outcomes":[{"text":"The steel is plain but well forged.","effects":{"items":{"iron_sword":1}}}]},{"label":"Take a Leather Vest","outcomes":[{"text":"Sturdy and surprisingly light.","effects":{"items":{"leather_vest":1}}}]},{"label":"Take a bundle of Healing Pills","outcomes":[{"text":"Three pills wrapped in oiled paper.","effects":{"items":{"healing_pill":3}}}]}]},{"id":"hidden_alchemist","text":"A reclusive alchemist beckons you into his hut, shelves heavy with rare pills.","minAge":20,"minRealm":1,"weight":2,"once":true,"choices":[{"label":"Buy a Longevity Pill (120 gold)","if":["gold>=120"],"outcomes":[{"text":"He wraps it carefully. 'Do not waste it.'","effects":{"gold":-120,"items":{"longevity_pill":1}}}]},{"label":"Buy a Clarity Pill (60 gold)","if":["gold>=60"],"outcomes":[{"text":"A faint chill and then a sharp mind.","effects":{"gold":-60,"items":{"clarity_pill":1}}}]},{"label":"Just browse","outcomes":[{"text":"You leave with nothing but an education.","effects":{"intelligence":1}}]}]},{"id":"shrine","text":"In a forgotten grove you find a mossy shrine with an empty offering bowl.","minAge":14,"weight":3,"once":true,"choices":[{"label":"Offer 50 gold","if":["gold>=50"],"outcomes":[{"chance":0.6,"text":"The bowl glows. A pendant of cold jade rests where your coins lay.","effects":{"gold":-50,"karma":3,"items":{"qi_pendant":1}}},{"text":"The shrine stays silent, but you feel lighter for the gesture.","effects":{"gold":-50,"karma":5}}]},{"label":"Pray without an offering","outcomes":[{"text":"A quiet moment of peace.","effects":{"karma":1}}]}]},{"id":"festival","text":"The annual spirit festival fills the town with lanterns and merchants.","minAge":5,"weight":3,"choices":[{"label":"Browse the stalls (15 gold)","if":["gold>=15"],"outcomes":[{"text":"You find a rare pill at a bargain.","effects":{"gold":-15,"items":{"breakthrough_pill":1}}}]},{"label":"Show off cultivation tricks for coins","outcomes":[{"text":"The crowd cheers and tosses you coins.","effects":{"gold":15,"luck":1}}]},{"label":"Simply enjoy the festivities","outcomes":[{"text":"A joyful night.","effects":{"health":3,"luck":3}}]}]},{"id":"cave","text":"While wandering, you discover a hidden cave humming with spiritual energy.","minAge":10,"weight":4,"if":["luck>=25"],"choices":[{"label":"Enter the cave","outcomes":[{"chance":0.3,"scale":{"luck":0.005},"text":"Inside you find a pool of spirit liquid!","effects":{"qi":{"base":20,"perRealm":25},"luck":2}},{"text":"A beast lairs inside and mauls you.","effects":{"health":-25}}]},{"label":"Walk away","outcomes":[{"text":"Discretion is the better part of valor."}]}]},{"id":"herb","text":"You spot a glowing spirit herb growing on a cliff.","minAge":8,"weight":5,"choices":[{"label":"Eat it","outcomes":[{"chance":0.8,"text":"Warm energy floods your meridians.","effects":{"qi":{"base":15,"perRealm":15}}},{"text":"It was toxic!","effects":{"health":-20}}]},{"label":"Sell it at the market","outcomes":[{"text":"A herbalist pays well.","effects":{"gold":{"base":25,"perRealm":20}}}]}]},{"id":"inherit","text":"A crumbling ancient altar offers a trial: solve its formation to claim a cultivator's inheritance.","minAge":16,"minRealm":1,"weight":2,"choices":[{"label":"Attempt the trial","outcomes":[{"chance":0.2,"scale":{"intelligence":0.0067},"text":"The formation yields! A torrent of knowledge and qi fills you.","effects":{"qi":{"base":60,"perRealm":40},"lifespan":5,"intelligence":3}},{"text":"The formation backlashes violently.","effects":{"health":-30}}]},{"label":"Leave it undisturbed","outcomes":[{"text":"You leave the ancient relics in peace.","effects":{"karma":1}}]}]},{"id":"recruit","text":"Elders from the Azure Cloud Sect are recruiting disciples in nearby towns and test your talent.","minAge":13,"maxAge":45,"weight":6,"once":true,"if":["!sect"],"choices":[{"label":"Join the righteous Azure Cloud Sect","outcomes":[{"text":"You are accepted as an outer disciple.","effects":{"qi":20,"intelligence":3,"karma":3,"sect":"Azure Cloud Sect"}}]},{"label":"Join the shadowy Blood Moon Sect","outcomes":[{"text":"The Blood Moon Sect teaches fast but ruthless methods.","effects":{"qi":45,"karma":-15,"sect":"Blood Moon Sect"}}]},{"label":"Remain a rogue cultivator","outcomes":[{"text":"Freedom is its own reward.","effects":{"luck":3}}]}]},{"id":"hot_spring","text":"You find a steaming spring rich with spiritual energy, perfect for soothing aching bones.","minAge":8,"weight":6,"if":["health<60"],"choices":[{"label":"Soak for a few days","outcomes":[{"text":"The warmth seeps into your wounds.","effects":{"health":30}}]},{"label":"Press on","outcomes":[{"text":"There is no time to rest.","effects":{"qi":5}}]}]},{"id":"wandering_healer","text":"A traveling healer notices how worn you look and offers his help.","minAge":6,"weight":8,"if":["health<45"],"choices":[{"label":"Accept treatment (20 gold)","if":["gold>=20"],"outcomes":[{"text":"His needles and herbs work wonders.","effects":{"gold":-20,"health":35}}]},{"label":"Ask for charity","outcomes":[{"chance":0.6,"text":"He sighs, then treats you anyway.","effects":{"health":25,"karma":-1}},{"text":"He shakes his head and moves on."}]},{"label":"Politely refuse","outcomes":[{"text":"You wave him off.","effects":{"karma":1}}]}]},{"id":"hermit","text":"An old hermit watches you train and offers to take you as a disciple.","minAge":12,"minRealm":1,"weight":4,"once":true,"if":["!flag:master"],"choices":[{"label":"Kneel and accept him as master","outcomes":[{"text":"The hermit smiles. 'Good. Let us begin.'","effects":{"intelligence":8,"qi":40,"setFlags":["master"]}}]},{"label":"Politely decline","outcomes":[{"text":"He shrugs and wanders off.","effects":{"luck":-1}}]}]},{"id":"rivalmake","text":"A prideful young genius from a famous clan sneers at your humble origins.","minAge":14,"weight":4,"once":true,"if":["!flag:hasRival"],"choices":[{"label":"Vow to surpass him one day","outcomes":[{"text":"You make an enemy, and a goal.","effects":{"qi":10,"setFlags":["hasRival"]}}]},{"label":"Ignore him","outcomes":[{"text":"You let the insult pass.","effects":{"karma":2}}]}]},{"id":"companion","text":"A kind fellow cultivator has been traveling beside you for months. Your heart stirs.","minAge":18,"maxAge":150,"minRealm":1,"weight":3,"once":true,"choices":[{"label":"Confess your feelings","outcomes":[{"chance":0.55,"scale":{"luck":0.005},"text":"They smile. You have found a dao companion!","effects":{"luck":8,"health":5,"setFlags":["companion"]}},{"text":"They gently turn you down. It stings.","effects":{"health":-3}}]},{"label":"Remain good friends","outcomes":[{"text":"A friendship that endures.","effects":{"karma":2,"luck":2}}]}]},{"id":"betray","text":"A trusted sect brother steals your pills and frames you for the theft.","minAge":15,"weight":3,"once":true,"if":["sect"],"choices":[{"label":"Report him to the elders","outcomes":[{"chance":0.5,"text":"The elders investigate and punish him.","effects":{"karma":3,"items":{"breakthrough_pill":1}}},{"text":"No one believes you.","effects":{"luck":-3}}]},{"label":"Retaliate in secret","outcomes":[{"text":"You raid his stash. Justice, or revenge?","effects":{"karma":-10,"qi":20}}]}]},{"id":"mastertask","text":"Your master asks you to find a Soul Lotus to heal his failing health.","minAge":20,"weight":10,"once":true,"if":["since:master>=5"],"choices":[{"label":"Brave the Misty Swamp","outcomes":[{"chance":0.5,"text":"You return with the lotus. He is deeply moved.","effects":{"karma":6,"qi":50,"setFlags":["lotus"]}},{"text":"The swamp nearly kills you.","effects":{"health":-30}}]},{"label":"Say you're too busy","outcomes":[{"text":"Master says nothing, but his eyes dim.","effects":{"karma":-6}}]}]},{"id":"masterlegacy","text":"Your master lies on his deathbed and calls you close.","minAge":30,"minRealm":2,"weight":15,"once":true,"if":["since:master>=15"],"choices":[{"label":"Receive his legacy","outcomes":[{"if":["flag:lotus"],"text":"He transfers a lifetime of qi and wisdom into you, grateful for the Soul Lotus you once brought him.","effects":{"qi":250,"lifespan":20,"karma":5,"intelligence":5,"items":{"sage_jade":1}}},{"text":"He transfers a lifetime of qi and wisdom into you, and presses his old jade pendant into your palm.","effects":{"qi":150,"lifespan":20,"karma":5,"intelligence":5,"items":{"sage_jade":1}}}]}]},{"id":"rivalfinal","text":"Your old rival blocks your path, now your equal. Years of enmity come to a head.","minAge":30,"minRealm":2,"weight":15,"once":true,"if":["since:hasRival>=10"],"choices":[{"label":"Duel to the death","outcomes":[{"chance":0.5,"scale":{"realm":0.04,"luck":0.0025,"power":0.01},"text":"You defeat him and claim his treasures.","effects":{"gold":100,"qi":60,"karma":-5,"setFlags":["rivalDone"]}},{"text":"He cuts you down.","effects":{"health":-60,"setFlags":["rivalDone"]}}]},{"label":"Defeat him, then spare his life","outcomes":[{"chance":0.4,"scale":{"realm":0.04,"power":0.01},"text":"You win and spare him. He bows and departs.","effects":{"qi":40,"karma":10,"setFlags":["rivalDone"]}},{"text":"You lose narrowly, and he spares you instead.","effects":{"health":-35,"karma":2,"setFlags":["rivalDone"]}}]}]},{"id":"stranger","text":"An old man lies wounded by the roadside, clutching a worn jade token.","minAge":12,"weight":3,"once":true,"choices":[{"label":"Tend his wounds (10 gold)","if":["gold>=10"],"outcomes":[{"text":"He thanks you weakly and disappears into the night.","effects":{"gold":-10,"karma":8,"setFlags":["savedStranger"]}}]},{"label":"Walk past","outcomes":[{"text":"It's none of your business.","effects":{"karma":-3}}]}]},{"id":"stranger2","text":"A grand procession arrives at your door. The old man you saved is an elder of the Heavenly Pavilion, and he remembers you.","minAge":20,"weight":20,"once":true,"if":["since:savedStranger>=6"],"choices":[{"label":"Accept his gift of spirit treasures","outcomes":[{"text":"He grants you a treasure trove, including a robe woven with spirit silk.","effects":{"qi":120,"lifespan":10,"luck":8,"items":{"breakthrough_pill":1,"jade_robe":1}}}]},{"label":"Ask him to teach you","outcomes":[{"text":"He guides your understanding.","effects":{"intelligence":10,"qi":60,"karma":3}}]}]}]};
